const DIGIT_RUN = '[0-9]+(?:_[0-9]+)*'
const INTEGER_RE = new RegExp(`^[+-]?${DIGIT_RUN}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGIT_RUN}(?:\\.${DIGIT_RUN}(?:[eE][+-]?${DIGIT_RUN})?|[eE][+-]?${DIGIT_RUN})$`
)
const VALUE_STOP = new Set([' ', '\t', ',', ']', '}'])

export class Scanner {
  constructor(line, lineNo) {
    this.s = line
    this.lineNo = lineNo
    this.pos = 0
  }

  peek() {
    return this.s[this.pos]
  }

  eof() {
    return this.pos >= this.s.length
  }

  advance() {
    this.pos++
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  /** Skip spaces and tabs, then treat an unquoted `#`/`;` as end of line. */
  skipWsAndComment() {
    while (!this.eof() && (this.peek() === ' ' || this.peek() === '\t')) this.advance()
    if (!this.eof() && (this.peek() === '#' || this.peek() === ';')) this.pos = this.s.length
  }
}

/** Parse one name: a bare word or a quoted string. Returns the decoded text. */
export function parseName(p) {
  p.skipWsAndComment()
  const ch = p.peek()
  if (ch === undefined) p.fail('expected a name')
  if (ch === '"' || ch === "'") return parseQuotedText(p, ch)
  if (!NAME_CHAR.test(ch)) p.fail('expected a name')
  const start = p.pos
  while (!p.eof() && NAME_CHAR.test(p.peek())) p.advance()
  return p.s.slice(start, p.pos)
}

/** Parse `<name>` `.` `<name>` ... , with spaces/tabs allowed around each `.`. */
export function parseDottedName(p) {
  const parts = [parseName(p)]
  for (;;) {
    p.skipWsAndComment()
    if (p.peek() !== '.') break
    p.advance()
    parts.push(parseName(p))
  }
  return parts
}

function parseQuotedText(p, quote) {
  p.advance()
  let result = ''
