    for (;;) {
      if (p.eof()) p.fail('unterminated string')
      if (p.peek() === "'") {
        p.advance()
        return result
      }
      result += p.peek()
      p.advance()
    }
  }
  for (;;) {
    if (p.eof()) p.fail('unterminated string')
    const ch = p.peek()
    if (ch === '"') {
      p.advance()
      return result
    }
    if (ch === '\\') {
      p.advance()
      if (p.eof()) p.fail('unterminated string')
      const esc = p.peek()
      switch (esc) {
        case '"':
          result += '"'
          p.advance()
          break
        case '\\':
          result += '\\'
          p.advance()
          break
        case 'n':
          result += '\n'
          p.advance()
          break
        case 't':
          result += '\t'
          p.advance()
          break
        case 'r':
          result += '\r'
          p.advance()
          break
        case '0':
          result += '\0'
          p.advance()
          break
