 * Builds the document tree: a `table` node holding `children`, `array`,
 * `aot` (array of tables), `string`, `integer`, `float` and `boolean`
 * nodes. `[name]` and `[[name]]` headers change the table current
 * assignments land in; every other non-blank, non-comment line assigns a
 * dotted key inside it.
 */
import { ParseError } from './errors.js'
import { Scanner, parseDottedName, parseValue, joinKey, descendTable } from './lineScanner.js'

function isNoopLine(line) {
  let i = 0
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  if (i >= line.length) return true
  return line[i] === '#' || line[i] === ';'
}

function newTable(path, headerDefined) {
  return { type: 'table', path, children: new Map(), headerDefined }
}

function applyTableHeader(p, root, dotted) {
  let node = root
  for (let i = 0; i < dotted.length - 1; i++) node = descendTable(p, node, dotted[i])
  const lastKey = dotted[dotted.length - 1]
  const fullPath = joinKey(node.path, lastKey)
  if (node.children.has(lastKey)) {
    const existing = node.children.get(lastKey)
    if (existing.type !== 'table') p.fail(`${fullPath} is not a table`)
    if (existing.headerDefined) p.fail(`table ${fullPath} is defined twice`)
    existing.headerDefined = true
    return existing
  }
  const table = newTable(fullPath, true)
  node.children.set(lastKey, table)
  return table
}

function applyArrayHeader(p, root, dotted) {
  let node = root
  for (let i = 0; i < dotted.length - 1; i++) node = descendTable(p, node, dotted[i])
  const lastKey = dotted[dotted.length - 1]
  const fullPath = joinKey(node.path, lastKey)
  let aot
  if (node.children.has(lastKey)) {
    const existing = node.children.get(lastKey)
    if (existing.type !== 'aot') p.fail(`${fullPath} is not an array of tables`)
    aot = existing
  } else {
    aot = { type: 'aot', path: fullPath, items: [] }
    node.children.set(lastKey, aot)
  }
  const elem = newTable(`${fullPath}[${aot.items.length}]`, false)
  aot.items.push(elem)
  return elem
}

