function compareCodePoints(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const da = ca[i].codePointAt(0)
    const db = cb[i].codePointAt(0)
    if (da !== db) return da - db
  }
  return ca.length - cb.length
}

function sortedKeys(table) {
  return [...table.children.keys()].sort(compareCodePoints)
}

function jsonValue(node, indent) {
  switch (node.type) {
    case 'boolean':
      return String(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'string':
      return JSON.stringify(node.value)
    case 'array':
      return jsonArray(node.items, indent)
    case 'aot':
      return jsonArray(node.items, indent)
    case 'table':
      return jsonTable(node, indent)
    default:
      throw new Error(`unreachable node type ${node.type}`)
  }
}

function jsonArray(items, indent) {
  if (items.length === 0) return '[]'
  const inner = indent + '  '
  const body = items.map((it) => inner + jsonValue(it, inner)).join(',\n')
  return `[\n${body}\n${indent}]`
}

function jsonTable(table, indent) {
  const keys = sortedKeys(table)
  if (keys.length === 0) return '{}'
  const inner = indent + '  '
  const body = keys
    .map((k) => `${inner}${JSON.stringify(k)}: ${jsonValue(table.children.get(k), inner)}`)
    .join(',\n')
  return `{\n${body}\n${indent}}`
}

export function toJson(root) {
  return jsonValue(root, '') + '\n'
}

function typeOf(node) {
  switch (node.type) {
    case 'table':
      return 'table'
    case 'aot':
    case 'array':
      return 'array'
    default:
      return node.type
  }
}

function emit(node, path, out) {
  out.push(`${path} ${typeOf(node)}`)
  if (node.type === 'table') {
    for (const key of sortedKeys(node)) emit(node.children.get(key), `${path}.${key}`, out)
  } else if (node.type === 'array' || node.type === 'aot') {
    node.items.forEach((item, idx) => emit(item, `${path}[${idx}]`, out))
  }
